std::ptrdiff_t get_parallel_threshold(size_t num_threads) {
    // L2 cache per core ≈ 1.25MB on Raptor Lake
    // We want each thread's partition to fit in L2
    constexpr size_t L2_CACHE_SIZE = 1280 * 1024;  // 1.25MB
    constexpr size_t ELEMENT_SIZE = sizeof(int);    // 4 bytes

    // Target: each partition should be < L2_CACHE_SIZE / 2
    // to leave room for pivot comparisons and temp storage
