namespace dual_pivot {

// Thread-local index to identify worker threads
// -1 indicates an external thread (e.g., main thread)
inline thread_local int thread_index = -1;

/**
 * @brief Lock-Free Work Stealing Thread Pool (V4)
 *
 * Uses Chase-Lev deques for lock-free work stealing:
 * - Owner push/pop are wait-free (no contention)
 * - Thief steal uses CAS (lock-free, not blocking)
 * - No mutex overhead for queue operations
 *
 * Key improvements over V3:
 * - Eliminates sched_yield() overhead (was 37.8% of time)
 * - Reduces pthread_mutex calls to zero for queue ops
 * - Better cache behavior with aligned atomic operations
 */
class ThreadPool {
private:
    // Lock-free deques for each worker
    std::vector<std::unique_ptr<ChaseLevDeque<4096>>> queues;
    std::vector<std::thread> workers;

    alignas(64) std::atomic<bool> stop{false};
    alignas(64) std::atomic<long> incomplete_tasks{0};

    // For wait_for_completion (still needs mutex for condition variable)
    std::mutex wait_mutex;
    std::condition_variable wait_cv;

    // Profiling
    std::atomic<long> tasks_pushed{0};
    std::atomic<long> tasks_executed{0};
    std::atomic<long> steal_attempts{0};
    std::atomic<long> steal_successes{0};
    std::atomic<long> local_pops{0};

public:
    void reset_stats() {
        tasks_pushed = 0;
        tasks_executed = 0;
        steal_attempts = 0;
        steal_successes = 0;
        local_pops = 0;
    }

    long get_tasks_pushed() const { return tasks_pushed; }
    long get_tasks_executed() const { return tasks_executed; }
    long get_steal_attempts() const { return steal_attempts; }
    long get_steal_successes() const { return steal_successes; }
    long get_local_pops() const { return local_pops; }
    size_t get_thread_count() const { return workers.size(); }

    long get_active_task_count() const {
        return incomplete_tasks.load(std::memory_order_relaxed);
    }

    ThreadPool(size_t num_threads = std::thread::hardware_concurrency()) {
        queues.reserve(num_threads);
        for (size_t i = 0; i < num_threads; ++i) {
            queues.push_back(std::make_unique<ChaseLevDeque<4096>>());
        }

        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back([this, i, num_threads] {
                thread_index = static_cast<int>(i);

                // Sticky victim for cache locality
                size_t last_victim = (i + 1) % num_threads;

                // Backoff counter for empty queue spinning
                int backoff = 0;
                constexpr int MAX_BACKOFF = 16;

                while (!stop.load(std::memory_order_relaxed)) {
                    std::function<void()>* task = nullptr;
                    bool found = false;

                    // 1. Try Local Pop (lock-free, wait-free)
                    task = queues[i]->pop();
                    if (task) {
                        found = true;
                        local_pops.fetch_add(1, std::memory_order_relaxed);
                        backoff = 0;
                    }
                    // 2. Try Steal (lock-free with CAS)
                    else {
                        steal_attempts.fetch_add(1, std::memory_order_relaxed);

                        // Scan for victims starting from last successful victim
                        for (size_t k = 0; k < num_threads; ++k) {
                            size_t victim = (last_victim + k) % num_threads;
                            if (victim == i) continue;

                            task = queues[victim]->steal();
                            if (task) {
                                found = true;
                                steal_successes.fetch_add(1, std::memory_order_relaxed);
                                last_victim = victim;
                                backoff = 0;
                                break;
                            }
                        }
                    }

                    if (found) {
                        try {
                            (*task)();
                        } catch (...) {
                            delete task;
                            long remaining = incomplete_tasks.fetch_sub(1, std::memory_order_acq_rel) - 1;
                            if (remaining == 0) {
                                wait_cv.notify_all();
                            }
                            throw;
                        }

                        delete task;
                        tasks_executed.fetch_add(1, std::memory_order_relaxed);
                        long remaining = incomplete_tasks.fetch_sub(1, std::memory_order_acq_rel) - 1;
                        if (remaining == 0) {
                            wait_cv.notify_all();
                        }
                    } else {
                        // Exponential backoff to reduce CPU spinning
                        if (backoff < MAX_BACKOFF) {
                            // Spin for a short time
                            for (int j = 0; j < (1 << backoff); ++j) {
                                // CPU pause instruction for hyperthreading friendliness
                                #if defined(__x86_64__) || defined(_M_X64) || defined(__i386__) || defined(_M_IX86)
                                    __builtin_ia32_pause();
                                #else
                                    std::atomic_thread_fence(std::memory_order_seq_cst);
                                #endif
                            }
                            backoff++;
                        } else {
                            // After max backoff, yield to OS scheduler
                            std::this_thread::yield();
                        }
                    }
                }
            });
        }
    }

    ~ThreadPool() {
        stop.store(true, std::memory_order_release);
        for (auto& worker : workers) {
            if (worker.joinable()) worker.join();
        }
    }

    template<typename F>
    void submit(F&& f) {
        incomplete_tasks.fetch_add(1, std::memory_order_acq_rel);

        int idx = thread_index;
        if (idx == -1) idx = 0;
        if (idx >= static_cast<int>(queues.size())) idx = 0;

        queues[idx]->push(std::forward<F>(f));
        tasks_pushed.fetch_add(1, std::memory_order_relaxed);
    }

    void wait_for_completion() {
        while (true) {
            if (incomplete_tasks.load(std::memory_order_acquire) == 0) {
                return;
            }

            std::unique_lock<std::mutex> lock(wait_mutex);
            wait_cv.wait_for(lock, std::chrono::microseconds(100));
        }
    }
};

// Singleton accessor with re-initialization support
inline std::unique_ptr<ThreadPool>& getThreadPoolInstance() {
    static std::unique_ptr<ThreadPool> pool;
    return pool;
}

inline ThreadPool& getThreadPool(int num_threads = 0) {
    auto& pool = getThreadPoolInstance();
    if (!pool) {
        pool = std::make_unique<ThreadPool>(num_threads > 0 ? num_threads : std::thread::hardware_concurrency());
    } else if (num_threads > 0 && pool->get_thread_count() != static_cast<size_t>(num_threads)) {
        pool = std::make_unique<ThreadPool>(num_threads);
    }
