def windows_to_wsl_path(win_path):
    """Convert Windows path to WSL path (e.g., C:\\Users\\... -> /mnt/c/Users/...)"""
    # Normalize the path
    path = os.path.normpath(win_path)
    # Replace drive letter (e.g., C: -> /mnt/c)
